sp_HomeKPIs	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_HomeKPIs`(\nIN p_idEmpresa INT,\nIN p_dataInicio DATETIME,\nIN p_dataFim    DATETIME\n)\nBEGIN\n    \n    SELECT\n        COUNT(*)                     AS totalPedidosMes,\n        COALESCE(SUM(valorTotal), 0) AS faturamentoMes,\n        COALESCE(AVG(valorTotal), 0) AS ticketMedio,\n        \n        (SELECT COUNT(*) FROM Pedido\n         WHERE idEmpresa = p_idEmpresa\n           AND dthPedido >= DATE_FORMAT(DATE_SUB(p_dataInicio, INTERVAL 1 MONTH), '%Y-%m-01')\n           AND dthPedido <  DATE_FORMAT(p_dataInicio, '%Y-%m-01')) AS totalPedidosMesAnterior,\n        (SELECT COALESCE(SUM(valorTotal), 0) FROM Pedido\n         WHERE idEmpresa = p_idEmpresa\n           AND dthPedido >= DATE_FORMAT(DATE_SUB(p_dataInicio, INTERVAL 1 MONTH), '%Y-%m-01')\n           AND dthPedido <  DATE_FORMAT(p_dataInicio, '%Y-%m-01')) AS faturamentoMesAnterior\n    FROM Pedido\n    WHERE idEmpresa = p_idEmpresa\n      AND dthPedido BETWEEN p_dataInicio AND p_dataFim;\n\n    \n    SELECT\n        COUNT(*)                                     AS totalClientes,\n        SUM(CASE WHEN fAtivo = 1 THEN 1 ELSE 0 END) AS clientesAtivos,\n        COALESCE(SUM(saldoDevedor), 0)               AS saldoDevedorTotal\n    FROM Cliente\n    WHERE idEmpresa = p_idEmpresa;\n\n    \n    SELECT\n        COUNT(*)  AS produtosEstoqueCritico,\n        (SELECT COUNT(*) FROM Estoque WHERE idEmpresa = p_idEmpresa) AS totalProdutos\n    FROM Estoque\n    WHERE idEmpresa = p_idEmpresa\n      AND QtdeAtual < estoqueMin;\n\n    \n    SELECT\n        fAtivo                        AS caixaAberto,\n        COALESCE(saldoInicial, 0)     AS saldoInicial,\n        COALESCE((\n            SELECT SUM(lc.valor)\n            FROM LancamentoCaixa lc\n            JOIN CategoriaFinanceira cf ON cf.idCategoriaFinanceira = lc.idCategoriaFinanceira\n            WHERE lc.idCaixa = c.idCaixa AND cf.tipo = 1\n        ), 0) AS totalEntradas,\n        COALESCE((\n            SELECT SUM(lc.valor)\n            FROM LancamentoCaixa lc\n            JOIN CategoriaFinanceira cf ON cf.idCategoriaFinanceira = lc.idCategoriaFinanceira\n            WHERE lc.idCaixa = c.idCaixa AND cf.tipo = 2\n        ), 0) AS totalSaidas\n    FROM Caixa c\n    WHERE c.idEmpresa = p_idEmpresa\n      AND c.fAtivo = 1\n    LIMIT 1;\n\n    \n    SELECT\n        sp.nome           AS statusNome,\n        COUNT(p.idPedido) AS QtdeAtual\n    FROM StatusPedido sp\n    LEFT JOIN Pedido p\n        ON p.statusPedido_id = sp.idStatusPedido\n       AND p.idEmpresa       = p_idEmpresa\n       AND p.dthPedido BETWEEN p_dataInicio AND p_dataFim\n    GROUP BY sp.idStatusPedido, sp.nome\n    ORDER BY sp.idStatusPedido;\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
